/**
 * @name Path traversal from user input to file operations
 * @description User-controlled file paths can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-taint
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // CLI arguments - sys.argv is a list, so we track its subscript access
    exists(DataFlow::Node argv |
      argv = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() and
      source = argv
    )
    or
    // argparse arguments - track attribute access on the returned namespace object
    exists(DataFlow::Node parseArgs |
      parseArgs = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = parseArgs
    )
    or
    // Track attribute access on argparse namespace
    exists(DataFlow::AttrRead attr |
      attr.getObject() = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from user input $@.", source.getNode(), "user input"

/**
 * @name CLI argument to file open without validation
 * @description User-controlled file paths in CLI without validation can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/cli-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CLIPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Track argparse argument values
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("add_argument").getACall() and
      source = call.getArg(0)
    )
    or
    // Track sys.argv directly
    source = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource()
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    sink = API::builtin("open").getACall().getArg(0)
    or
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module CLIPathTraversalFlow = TaintTracking::Global<CLIPathTraversalConfig>;
import CLIPathTraversalFlow::PathGraph

from CLIPathTraversalFlow::PathNode source, CLIPathTraversalFlow::PathNode sink
where CLIPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "CLI argument flows to file operation $@.", source.getNode(), "here"

/**
 * @name ReDoS - User input to regex pattern
 * @description User-controlled data used in regex patterns can cause ReDoS
 * @kind path-problem
 * @problem.severity error
 * @id py/redos-user-input
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any external/untrusted input - could come from JSON schema being validated
    exists(DataFlow::CallCfgNode call |
      // JSON loads - schemas can come from external sources
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() and
      source = call
    )
    or
    // CLI arguments
    exists(DataFlow::Node argv |
      argv = API::moduleImport("sys").getMember("argv").getAValueReachableFromSource() and
      source = argv
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // re.compile or re.match/search/findall with pattern argument
      call = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "fullmatch"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regular expression pattern from untrusted input $@.", source.getNode(), "source"

/**
 * @name Server-Side Request Forgery via schema reference
 * @description User-controlled URLs in JSON schema references can lead to SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-schema-reference
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Track file input that could contain user-controlled schema references
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("json").getMember(["load", "loads"]).getACall() and
      source = call
    )
    or
    // Track argument parsing
    exists(DataFlow::AttrRead attr |
      attr.getObject() = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("urllib").getMember("request").getMember(["urlopen", "urlretrieve"]).getACall() or
        call = API::moduleImport("requests").getMember(["get", "post", "request"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF via user-controlled schema reference $@.", source.getNode(), "user input"
